mapper.select:
SELECT user_id, email, user_name, phone, user_type
FROM user
WHERE email = #{sId}

mapper.update:
UPDATE user
SET user_name = #{userName},
    phone = #{phone}
WHERE email = #{email}

mapper.select:
SELECT password
FROM user
WHERE email = #{sId}

mapper.update:
UPDATE user
SET password = #{password}
WHERE email = #{sId}

mapper.select:
SELECT jp.job_id , jp.comp_id , uc.company_name , jp.title , jp.exp_type , jp.exp_year , jp.edu , jp.emp_type , jp.address , jp.close_date , (jp.close_date < CURDATE()) AS closed , DATE_FORMAT(jp.close_date, '~ %m/%d(%a)') AS deadline_label FROM JOB_SCRAP js INNER JOIN JOB_POSTING jp ON jp.job_id = js.job_id INNER JOIN USER_COMPANY uc ON uc.user_id = jp.comp_id WHERE js.user_id = #{userId}
AND ( jp.title LIKE CONCAT('%', #{keyword}, '%') OR uc.company_name LIKE CONCAT('%', #{keyword}, '%') )
AND jp.close_date >= CURDATE()
AND jp.close_date < CURDATE()
AND NOT EXISTS ( SELECT 1 FROM JOB_APPLICATION ja WHERE ja.user_id = js.user_id AND ja.job_id = js.job_id )
ORDER BY js.created_at DESC LIMIT #{page.offset, jdbcType=INTEGER}, #{page.safeSize, jdbcType=INTEGER}
